import re
t=open('TODO.md').read()
def slug(h):
    h=h.lower().strip(); h=re.sub(r'[^\w\s-]','',h); return h.replace(' ','-')
heads=set(slug(m.group(1)) for m in re.finditer(r'^#+\s+(.*)$',t,re.M))
defs=dict(re.findall(r'^\[(\d+)\]:\s*(\S+)',t,re.M))
for n,tgt in defs.items():
    if tgt.startswith('#') and tgt[1:] not in heads: print('BAD',n,tgt)
print('ok'); 
EOF
